      const row=document.createElement('div');row.className='combat-roll-row';card.classList.add('combat-card-compact');if(a.equipped)card.classList.add('equipped-weapon-card');const image=document.createElement('img');image.className='combat-weapon-image';image.alt=a.name;const catalogImage=itemCatalog.find(c=>c.type==='weapon'&&c.name===a.name)?.image;image.src=a.image||catalogImage||combatFallbackImage(a.id==='unarmed'||/desarmado/i.test(a.name));card.append(image);
      const attack=document.createElement('button');attack.type='button';const v=attackValues(a);attack.textContent=(1+Math.abs(v.attr))+'d20\nATAQUE';attack.addEventListener('click',()=>{const current=attackValues(a);const pool=rollPendingSkill(a.skill,current.attr);const crit=a.critical<=20&&(pool.value>=a.critical||pool.value===20);attackCriticalState[a.id]=crit;showSkillDice(pool,crit?'CRÍTICO':classifySkill(pool.value,current.targets),a.name);});
      const damage=document.createElement('button');damage.type='button';const bonus=a.attr==='none'?0:Number(state.attrs[a.attr])||0;damage.textContent=a.damage?a.damage+(bonus>=0?' +':' ')+bonus+'\nDANO':'Configurar\nDANO';damage.addEventListener('click',()=>{if(!a.damage){openAttack(a);return;}try{const crit=Boolean(attackCriticalState[a.id]);const b=a.attr==='none'?0:Number(state.attrs[a.attr])||0;const pool=rollDamage(a.damage,crit?a.mult:1,b);pool.detail='Dados: '+pool.dice.join(', ')+' · '+a.damage+' · atributo '+b+(crit?' · crítico ×'+a.mult:'');showSkillDice(pool,crit?'DANO CRÍTICO':'DANO',a.name);delete attackCriticalState[a.id];}catch(e){toast(e.message);}});
