var ritualReady=true;
let ritualDetailOpen=false;
function ritualState(){if(!state.rituals||Array.isArray(state.rituals))state.rituals={known:[],selected:null,cursedItemId:null};return state.rituals;}
function ritualCommit(change){const previous=JSON.stringify(ritualState());change(ritualState());try{localStorage.setItem(window.SeasonContext.stateKey,JSON.stringify(state));window.dispatchEvent(new Event('season:change'));$('ritual-save-error').textContent='';renderRituals();return true;}catch(e){state.rituals=JSON.parse(previous);$('ritual-save-error').textContent='Não foi possível salvar os rituais. Libere espaço no navegador.';toast('Não foi possível salvar a alteração.');return false;}}
function ritualText(tag,text,className){const el=document.createElement(tag);el.textContent=text;if(className)el.className=className;return el;}
function renderRitualDetails(ritual,target='ritual-detail-content'){const panel=$(target);panel.replaceChildren();if(!ritual){panel.append(ritualText('p','Selecione um ritual para ver sua imagem e informações de conjuração.'));return;}if(ritualSigilsOffline[ritual.name]){const image=document.createElement('img');image.src=ritualSigilsOffline[ritual.name];image.alt='Símbolo de '+ritual.name;image.className='ritual-detail-image';panel.append(image);}panel.append(ritualText('h3',ritual.name));const meta=document.createElement('dl');meta.className='ritual-meta';for(const [label,key] of [['Elemento','element'],['Círculo','circle'],['Custo','cost'],['Execução','cast'],['Alcance','range'],['Alvo / Área','target'],['Duração','duration'],['Resistência','resistance']]){const cell=document.createElement('div');cell.append(ritualText('dt',label),ritualText('dd',ritual[key]||'—'));meta.append(cell);}panel.append(meta);for(const [label,key] of [['Normal','desc'],['Discente','discente'],['Verdadeiro','verdadeiro']]){if(!ritual[key])continue;panel.append(ritualText('h4',label),ritualText('p',ritual[key]));}if(target==='ritual-catalog-preview'){const add=ritualText('button',ritualState().known.includes(ritual.name)?'Já adquirido':'＋ Adquirir ritual');add.type='button';add.className='ritual-popup-acquire';add.disabled=ritualState().known.includes(ritual.name);add.onclick=()=>{if(ritualCommit(s=>{if(!s.known.includes(ritual.name))s.known.push(ritual.name);s.selected=ritual.name;}))renderRitualCatalog();};panel.append(add);return;}const remove=ritualText('button','Remover ritual');remove.type='button';remove.onclick=()=>ritualCommit(s=>{s.known=s.known.filter(n=>n!==ritual.name);if(s.selected===ritual.name)s.selected=s.known[0]||null;});panel.append(remove);}
function renderRituals(){const s=ritualState(),list=$('ritual-saved-list');list.replaceChildren();$('ritual-total').textContent=s.known.length+(s.known.length===1?' ritual':' rituais');if(!s.known.length)list.append(ritualText('p','Nenhum ritual adquirido. Use + Adquirir ritual.'));for(const name of s.known){const r=ritualCatalogOffline.find(r=>r.name===name);if(!r)continue;const card=document.createElement('button');card.type='button';card.className='ritual-saved-card';card.setAttribute('aria-pressed',String(s.selected===name));if(ritualSigilsOffline[name]){const img=document.createElement('img');img.src=ritualSigilsOffline[name];img.alt='';img.loading='lazy';card.append(img);}const label=document.createElement('span');label.append(ritualText('strong',name),ritualText('small',r.element+' · '+r.circle+'º círculo · '+r.cost));card.append(label);card.onclick=()=>{ritualDetailOpen=true;if(ritualCommit(s=>{s.selected=name;}))setRitualDetailOpen(true);else setRitualDetailOpen(false);};list.append(card);}renderRitualDetails(ritualCatalogOffline.find(r=>r.name===s.selected));setRitualDetailOpen(ritualDetailOpen&&s.known.includes(s.selected));const item=inventoryState().items.find(i=>i.id===s.cursedItemId);inventoryPaintSlot($('ritual-cursed-slot'),item,'Vincular item do inventário');$('ritual-cursed-clear').hidden=!item;}
let ritualPreviewName=null;
function ritualAccent(r){return {Conhecimento:'#d3b55f',Energia:'#bd83ed',Medo:'#d9d9dc',Morte:'#a5a6b5',Sangue:'#e56960'}[r.element]||'#db9c72';}
function renderRitualCatalog(){const query=ammoNormalize($('ritual-search').value),element=$('ritual-filter-element').value,circle=$('ritual-filter-circle').value,list=$('ritual-catalog-list');list.replaceChildren();const matches=ritualCatalogOffline.filter(r=>ammoNormalize(r.name+' '+r.element).includes(query)&&(!element||(r.elements||[r.element]).includes(element))&&(!circle||String(r.circle)===circle)).sort((a,b)=>Number(a.circle)-Number(b.circle)||a.name.localeCompare(b.name,'pt-BR'));$('ritual-catalog-count').textContent=matches.length+' encontrados · '+ritualCatalogOffline.length+' rituais';if(!matches.some(r=>r.name===ritualPreviewName))ritualPreviewName=null;if(!matches.length)list.append(ritualText('p','Nenhum ritual corresponde aos filtros.'));for(const r of matches){const row=document.createElement('button');row.type='button';row.className='ritual-catalog-entry';row.style.setProperty('--ritual-accent',ritualAccent(r));row.setAttribute('aria-pressed',String(r.name===ritualPreviewName));if(ritualSigilsOffline[r.name]){const img=document.createElement('img');img.src=ritualSigilsOffline[r.name];img.alt='';img.loading='lazy';row.append(img);}row.append(ritualText('strong',r.name));const chips=document.createElement('small');for(const text of [r.element,r.circle+'º círculo',r.cost])chips.append(ritualText('span',text));row.append(chips);if(ritualState().known.includes(r.name))row.append(ritualText('span','Adquirido','ritual-acquired-label'));row.onclick=()=>{const scroll=list.scrollTop;ritualPreviewName=r.name;renderRitualCatalog();list.scrollTop=scroll;$('ritual-catalog-preview').scrollTop=0;};list.append(row);}renderRitualDetails(ritualCatalogOffline.find(r=>r.name===ritualPreviewName),'ritual-catalog-preview');}
$('ritual-acquire').onclick=()=>{$('ritual-search').value='';$('ritual-filter-element').value='';$('ritual-filter-circle').value='';ritualPreviewName=null;renderRitualCatalog();$('ritual-acquire-dialog').showModal();};$('ritual-search').oninput=renderRitualCatalog;$('ritual-filter-element').onchange=renderRitualCatalog;$('ritual-filter-circle').onchange=renderRitualCatalog;$('ritual-acquire-close').onclick=()=>$('ritual-acquire-dialog').close();
$('ritual-cursed-slot').onclick=()=>{const list=$('ritual-cursed-options');list.replaceChildren();const items=inventoryState().items;if(!items.length)list.append(ritualText('p','Adicione um item ao inventário primeiro.'));for(const item of items){const b=document.createElement('button');b.type='button';b.className='item-slot';inventoryPaintSlot(b,item,'');b.onclick=()=>{if(ritualCommit(s=>{s.cursedItemId=item.id;}))$('ritual-cursed-dialog').close();};list.append(b);}$('ritual-cursed-dialog').showModal();};$('ritual-cursed-close').onclick=()=>$('ritual-cursed-dialog').close();$('ritual-cursed-clear').onclick=()=>ritualCommit(s=>{s.cursedItemId=null;});

function setRitualDetailOpen(open){ritualDetailOpen=Boolean(open);const panel=$('ritual-detail-panel');panel.classList.toggle('ritual-detail-closed',!ritualDetailOpen);panel.setAttribute('aria-hidden',String(!ritualDetailOpen));panel.inert=!ritualDetailOpen;}
$('ritual-detail-close').onclick=()=>{setRitualDetailOpen(false);const active=$('ritual-saved-list').querySelector('[aria-pressed="true"]');active?.focus();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ritualDetailOpen&&!document.querySelector('dialog[open]'))setRitualDetailOpen(false);});

